import React, { useState, useEffect } from "react";
import Sidebarmov from "../../components/Sidebarmov";
import HeaderPanel from "../../components/HeaderPanel";
import "../../components/admin.css"; 
import axios from 'axios'; 
// Asegúrate de usar el puerto correcto (3001 según tu código)
const API_URL = "http://localhost:3001/api/productos"; 
// Asume que tienes otras rutas para Categorías
const CATEGORIAS_URL = "http://localhost:3001/api/categorias"; 
const CLASIFICACIONES_URL = "http://localhost:3001/api/clasificaciones"; 

export default function FormularioEntradaProducto() {
    // === ESTADOS BASE ===
    const [formData, setFormData] = useState({
        id_producto: '',
        cantidad_m: '',
        observaciones: '',
        id_usuario: 1, // Asume un ID de usuario fijo o obtenlo del contexto
    });

    // === ESTADOS DINÁMICOS PARA PRODUCTO NUEVO ===
    const [nuevoProductoData, setNuevoProductoData] = useState({
        nom_producto: '',
        precio_unitario: '',
        stock_minimo: 0,
        color: '',
        talla: '',
        tamaño: '',
        descripcion: '',
        id_categoria: '',
        id_clasificacion: '',
    });

    const [imagen, setImagen] = useState(null); // Para el archivo de imagen
    const [esNuevo, setEsNuevo] = useState(false); // Bandera para renderizado condicional

    // === ESTADOS DE UI Y DATOS EXTERNOS ===
    const [productoExistente, setProductoExistente] = useState(null);
    const [categorias, setCategorias] = useState([]);
    const [clasificaciones, setClasificaciones] = useState([]);

    const [mensaje, setMensaje] = useState({ text: '', type: '' });
    const [cargando, setCargando] = useState(false);

    // useEffect para cargar categorías y clasificaciones al inicio
    useEffect(() => {
        const fetchExternalData = async () => {
            try {
                const [catRes, clasRes] = await Promise.all([
                    axios.get(CATEGORIAS_URL),
                    axios.get(CLASIFICACIONES_URL),
                ]);
                setCategorias(catRes.data);
                setClasificaciones(clasRes.data);
            } catch (error) {
                console.error("Error al cargar datos externos:", error);
                setMensaje({ text: 'Error al cargar categorías/clasificaciones.', type: 'error' });
            }
        };
        fetchExternalData();
    }, []);

    // Manejar cambios en el formulario (ID, Cantidad, Observaciones)
    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    // Manejar cambios en los campos de NUEVO PRODUCTO
    const handleNuevoChange = (e) => {
        const { name, value } = e.target;
        setNuevoProductoData(prev => ({ ...prev, [name]: value }));
    };

    // Manejar cambio de imagen
    const handleImageChange = (e) => {
        setImagen(e.target.files[0]);
    };

    // Lógica para buscar producto o activar modo 'Nuevo'
    const handleCheckProducto = async (e) => {
        if (e.key === 'Enter') {
            e.preventDefault(); 

            const id = formData.id_producto;
            if (!id) return;

            setCargando(true);
            setMensaje({ text: '', type: '' });
            setProductoExistente(null);
            setEsNuevo(false); // Resetear modo nuevo
            handleResetNuevoProductoData(); // Limpiar campos de nuevo producto

            try {
                const response = await axios.get(`${API_URL}/check/${id}`);

                if (response.data.found) {
                    setProductoExistente(response.data.product);
                    setMensaje({ text: `Producto encontrado: ${response.data.product.nom_producto}. Stock actual: ${response.data.product.stock_actual}`, type: 'success' });
                }
            } catch (error) {
                if (error.response && error.response.status === 404) {
                    // Producto NO encontrado -> Activa el modo 'Nuevo'
                    setEsNuevo(true);
                    setMensaje({ text: 'Producto no encontrado. Ingrese los datos para registrarlo como nuevo.', type: 'info' });
                } else {
                    console.error("Error al verificar producto:", error);
                    setMensaje({ text: 'Error de conexión con el servidor.', type: 'error' });
                }
            } finally {
                setCargando(false);
            }
        }
    };

    // Función de limpieza de estados
    const handleReset = () => {
        setFormData({ id_producto: '', cantidad_m: '', observaciones: '', id_usuario: 1 });
        handleResetNuevoProductoData();
        setProductoExistente(null);
        setEsNuevo(false);
        setMensaje({ text: '', type: '' });
        setCargando(false);
    };

    const handleResetNuevoProductoData = () => {
        setNuevoProductoData({
            nom_producto: '', precio_unitario: '', stock_minimo: 0, color: '', 
            talla: '', tamaño: '', descripcion: '', id_categoria: '', id_clasificacion: ''
        });
        setImagen(null);
    }

    // Manejar el envío del formulario
    const handleSubmit = async (e) => {
        e.preventDefault();

        setCargando(true);
        setMensaje({ text: '', type: '' });

        const isNewProduct = esNuevo;

        // 1. Crear FormData para enviar datos mixtos (JSON + Archivo)
        const data = new FormData();
        data.append('id_usuario', formData.id_usuario);
        data.append('cantidad_m', formData.cantidad_m);
        data.append('observaciones', formData.observaciones);
        data.append('es_nuevo_producto', isNewProduct ? 'true' : 'false');

        if (isNewProduct) {
            // Lógica para producto nuevo: Validar campos y adjuntar metadatos/imagen
            if (!nuevoProductoData.nom_producto || !nuevoProductoData.precio_unitario || !nuevoProductoData.id_categoria || !formData.cantidad_m) {
                setMensaje({ text: "Faltan campos obligatorios para el nuevo producto (Nombre, Precio, Categoría, Cantidad).", type: 'error' });
                setCargando(false); return;
            }
            Object.keys(nuevoProductoData).forEach(key => {
                data.append(key, nuevoProductoData[key]);
            });
            if (imagen) {
                data.append('imagen_producto', imagen);
            }
        } else {
            // Lógica para producto existente: Validar y adjuntar ID
            if (!productoExistente) {
                setMensaje({ text: 'Debe buscar un producto existente o registrar uno nuevo.', type: 'error' });
                setCargando(false); return;
            }
            if (!formData.cantidad_m || formData.cantidad_m <= 0) {
                setMensaje({ text: 'Ingrese una cantidad válida mayor a cero.', type: 'error' });
                setCargando(false); return;
            }
            data.append('id_producto_existente', formData.id_producto);
        }

        try {
            const response = await axios.post(`${API_URL}/inventario`, data, {
                headers: { 'Content-Type': 'multipart/form-data' }, // Necesario para enviar archivos
            });

            setMensaje({ 
                text: response.data.message || `Registro completado. ID: ${response.data.id_producto}`, 
                type: 'success' 
            });
            handleReset(); // Limpiar todo después de un éxito

        } catch (error) {
            console.error("Error al registrar:", error.response || error);
            const errorMessage = error.response?.data?.details || error.response?.data?.error || "Error al registrar la entrada/producto.";
            setMensaje({ text: errorMessage, type: 'error' });
        } finally {
            setCargando(false);
        }
    };

    return (
        <div className="dashboard-layout">
            <Sidebarmov />

            <main className="contenido">
                <HeaderPanel title={`📦 ${esNuevo ? 'Registro de Nuevo Producto' : 'Registro de Entrada de Stock'}`} />

                {mensaje.text && (
                    <div className={`alerta ${mensaje.type}`}>
                        {mensaje.text}
                    </div>
                )}

                <section className="cuadro-blanco form-producto">

                    <form className="formulario" onSubmit={handleSubmit}>

                        {/* === 1. BUSCADOR DE ID (Siempre visible) === */}
                        <div className="campo">
                            <label htmlFor="id_producto">ID del Producto</label>
                            <input 
                                type="number" 
                                id="id_producto" 
                                name="id_producto" 
                                placeholder="Ingrese el ID y presione ENTER para buscar" 
                                required 
                                value={formData.id_producto}
                                onChange={handleChange}
                                onKeyPress={handleCheckProducto}
                                disabled={cargando || esNuevo} // Deshabilita si es nuevo para forzar el modo
                            />
                            {cargando && <p className="cargando">Buscando...</p>}

                            {/* Mostrar estado de producto existente */}
                            {productoExistente && (
                                <p className="success-text">Producto existente: **{productoExistente.nom_producto}** | Stock: **{productoExistente.stock_actual}**</p>
                            )}
                        </div>

                        {/* === 2. CAMPOS DE STOCK (Visibles para ambos) === */}
                        {!esNuevo && (
                            <div className="campo">
                                <label htmlFor="stock_actual">Stock Actual</label>
                                <input 
                                    type="number" 
                                    id="stock_actual" 
                                    name="stock_actual" 
                                    readOnly 
                                    value={productoExistente ? productoExistente.stock_actual : ''}
                                    placeholder="N/A"
                                    className='info'
                                />
                            </div>
                        )}

                        <div className="campo">
                            <label htmlFor="cantidad_m">Cantidad de ENTRADA</label>
                            <input 
                                type="number" 
                                id="cantidad_m" 
                                name="cantidad_m" 
                                placeholder={esNuevo ? "Stock Inicial" : "Cantidad de unidades que entran"} 
                                required 
                                min="1"
                                value={formData.cantidad_m}
                                onChange={handleChange}
                                disabled={cargando || (!productoExistente && !esNuevo)} 
                            />
                        </div>

                        {/* === 3. CAMPOS DE NUEVO PRODUCTO (Condicionales) === */}
                        {esNuevo && (
                            <>
                                <h2>Detalles del Nuevo Producto</h2>

                                <div className="campo">
                                    <label htmlFor="nom_producto">Nombre del Producto *</label>
                                    <input type="text" id="nom_producto" name="nom_producto" placeholder="Ej: Sábana Paw Patrol" required value={nuevoProductoData.nom_producto} onChange={handleNuevoChange} />
                                </div>
                                <div className="campo">
                                    <label htmlFor="precio_unitario">Precio Unitario *</label>
                                    <input type="number" id="precio_unitario" name="precio_unitario" placeholder="Costo de venta" required value={nuevoProductoData.precio_unitario} onChange={handleNuevoChange} />
                                </div>
                                <div className="campo">
                                    <label htmlFor="stock_minimo">Stock Mínimo</label>
                                    <input type="number" id="stock_minimo" name="stock_minimo" placeholder="Mínimo para alerta" value={nuevoProductoData.stock_minimo} onChange={handleNuevoChange} />
                                </div>

                                {/* Selects para Categoría y Clasificación */}
                                <div className="campo">
                                    <label htmlFor="id_categoria">Categoría *</label>
                                    <select id="id_categoria" name="id_categoria" required value={nuevoProductoData.id_categoria} onChange={handleNuevoChange}>
                                        <option value="">Seleccione Categoría</option>
                                        {categorias.map(cat => (
                                            <option key={cat.id_categoria} value={cat.id_categoria}>{cat.nombre_c}</option>
                                        ))}
                                    </select>
                                </div>

                                <div className="campo">
                                    <label htmlFor="id_clasificacion">Clasificación</label>
                                    <select id="id_clasificacion" name="id_clasificacion" value={nuevoProductoData.id_clasificacion} onChange={handleNuevoChange}>
                                        <option value="">Seleccione Clasificación</option>
                                        {clasificaciones.map(clas => (
                                            <option key={clas.id_clasificacion} value={clas.id_clasificacion}>{clas.nombre_clas}</option>
                                        ))}
                                    </select>
                                </div>

                                {/* Imagen */}
                                <div className="campo">
                                    <label htmlFor="imagen_producto">Imagen del Producto</label>
                                    <input type="file" id="imagen_producto" name="imagen_producto" onChange={handleImageChange} accept="image/*" />
                                </div>

                                {/* Atributos opcionales */}
                                <div className="campo-grupo">
                                    <div className="campo">
                                        <label htmlFor="color">Color</label>
                                        <input type="text" id="color" name="color" value={nuevoProductoData.color} onChange={handleNuevoChange} />
                                    </div>
                                    <div className="campo">
                                        <label htmlFor="talla">Talla</label>
                                        <input type="text" id="talla" name="talla" value={nuevoProductoData.talla} onChange={handleNuevoChange} />
                                    </div>
                                    <div className="campo">
                                        <label htmlFor="tamaño">Tamaño</label>
                                        <input type="text" id="tamaño" name="tamaño" value={nuevoProductoData.tamaño} onChange={handleNuevoChange} />
                                    </div>
                                </div>

                                <div className="campo">
                                    <label htmlFor="descripcion">Descripción</label>
                                    <textarea id="descripcion" name="descripcion" placeholder="Detalles completos del producto..." rows="3" value={nuevoProductoData.descripcion} onChange={handleNuevoChange}></textarea>
                                </div>
                            </>
                        )}

                        {/* === 4. OBSERVACIONES Y BOTONES (Siempre visibles) === */}
                        <div className="campo">
                            <label htmlFor="observaciones">Observaciones (Proveedor, #Factura, etc.)</label>
                            <textarea 
                                id="observaciones" 
                                name="observaciones" 
                                placeholder="Ej: Recibido de Proveedor X con Factura #1234" 
                                rows="3"
                                value={formData.observaciones}
                                onChange={handleChange}
                                disabled={cargando}
                            ></textarea>
                        </div>

                        <div className="botones">
                            <button 
                                type="submit" 
                                className="btn-guardar" 
                                disabled={cargando || (!productoExistente && !esNuevo)}
                            >
                                <i className="fa-solid fa-floppy-disk"></i> 
                                {cargando ? 'Registrando...' : (esNuevo ? 'Registrar Producto y Stock' : 'Registrar Entrada')}
                            </button>
                            <button type="button" className="btn-cancelar" onClick={handleReset} disabled={cargando}>
                                <i className="fa-solid fa-xmark"></i> Cancelar / Limpiar
                            </button>
                        </div>
                    </form>
                </section>
            </main>
        </div>
    );
}
